Here is the commit message:
PCI/P2PDMA: Fix p2pmem_alloc_mmap() warning condition

Commit b7e282378773 has already changed the initial page refcount of
p2pdma page from one to zero, however, in p2pmem_alloc_mmap() it uses
"VM_WARN_ON_ONCE_PAGE(!page_ref_count(page))" to assert the initial page
refcount should not be zero and the following will be reported when
CONFIG_DEBUG_VM is enabled:

  page: refcount:0 mapcount:0 mapping:0000000000000000 index:0x0 pfn:0x380400000
  flags: 0x20000000002000(reserved|node=0|zone=4)
  raw: 0020000000002000 ff1100015e3ab440 0000000000000000 0000000000000000
  raw: 0000000000000000 0000000000000000 00000000ffffffff 0000000000000000
  page dumped because: VM_WARN_ON_ONCE_PAGE(!page_ref_count(page))
  ------------[ cut here ]------------
  WARNING: CPU: 5 PID: 449 at drivers/pci/p2pdma.c:240 p2pmem_alloc_mmap+0x83a/0xa60

Fix by using "page_ref_count(page)" as the assertion condition.

Fixes: b7e282378773 ("mm/mm_init: move p2pdma page refcount initialisation to p2pdma")
Signed-off-by: Hou Tao <houtao1@huawei.com>
Signed-off-by: Bjorn Helgaas <bhelgaas@google.com>
Reviewed-by: Logan Gunthorpe <logang@deltatee.com>
Reviewed-by: Alistair Popple <apopple@nvidia.com>
Link: https://patch.msgid.link/20251220040446.274991-3-houtao@huaweicloud.com

Here is the root cause:
After commit b7e282378773 changed the initial page refcount of p2pdma pages from 1 to 0, the VM_WARN_ON_ONCE_PAGE condition in p2pmem_alloc_mmap() was not updated. It still checked for refcount being zero (i.e., !page_ref_count(page)), which now incorrectly triggers a warning for every newly allocated page, because they all start with refcount 0. The warning should have been changed to check for non-zero refcount to detect unexpected usage.

Here is the patch:

 static int p2pmem_alloc_mmap(struct file *filp, struct kobject *kobj,
 		const struct bin_attribute *attr, struct vm_area_struct *vma)
 {
 	struct pci_dev *pdev = to_pci_dev(kobj_to_dev(kobj));
 	size_t len = vma->vm_end - vma->vm_start;
 	struct pci_p2pdma *p2pdma;
 	struct percpu_ref *ref;
 	unsigned long vaddr;
 	void *kaddr;
 	int ret;

 	/* prevent private mappings from being established */
 	if ((vma->vm_flags & VM_MAYSHARE) != VM_MAYSHARE) {
 		pci_info_ratelimited(pdev,
 				     "%s: fail, attempted private mapping\n",
 				     current->comm);
 		return -EINVAL;
 	}

 	if (vma->vm_pgoff) {
 		pci_info_ratelimited(pdev,
 				     "%s: fail, attempted mapping with non-zero offset\n",
 				     current->comm);
 		return -EINVAL;
 	}

 	rcu_read_lock();
 	p2pdma = rcu_dereference(pdev->p2pdma);
 	if (!p2pdma) {
 		ret = -ENODEV;
 		goto out;
 	}

 	kaddr = (void *)gen_pool_alloc_owner(p2pdma->pool, len, (void **)&ref);
 	if (!kaddr) {
 		ret = -ENOMEM;
 		goto out;
 	}

 	/*
 	 * vm_insert_page() can sleep, so a reference is taken to mapping
 	 * such that rcu_read_unlock() can be done before inserting the
 	 * pages
 	 */
 	if (unlikely(!percpu_ref_tryget_live_rcu(ref))) {
 		ret = -ENODEV;
 		goto out_free_mem;
 	}
 	rcu_read_unlock();

 	for (vaddr = vma->vm_start; vaddr < vma->vm_end; vaddr += PAGE_SIZE) {
 		struct page *page = virt_to_page(kaddr);

 		/*
 		 * Initialise the refcount for the freshly allocated page. As
 		 * we have just allocated the page no one else should be
 		 * using it.
 		 */
-		VM_WARN_ON_ONCE_PAGE(!page_ref_count(page), page);
+		VM_WARN_ON_ONCE_PAGE(page_ref_count(page), page);
 		set_page_count(page, 1);
 		ret = vm_insert_page(vma, vaddr, page);
 		if (ret) {
 			gen_pool_free(p2pdma->pool, (uintptr_t)kaddr, len);
 			percpu_ref_put(ref);
 			return ret;
 		}
 		percpu_ref_get(ref);
 		put_page(page);
 		kaddr += PAGE_SIZE;
 		len -= PAGE_SIZE;
 	}

 	percpu_ref_put(ref);

 	return 0;
 out_free_mem:
 	gen_pool_free(p2pdma->pool, (uintptr_t)kaddr, len);
 out:
 	rcu_read_unlock();
 	return ret;
 }



